mapper.select:
SELECT e.id as eventId, e.title, es.event_date as eventDate, v.venue_name as venueName, e.genre FROM tb_event e LEFT JOIN tb_event_schedule es ON e.id = es.event_id LEFT JOIN tb_venue v ON es.venue_id = v.id WHERE e.account_id = #{accountId} AND e.status = 'APPROVED' AND es.event_date >= NOW()
AND (es.event_date, e.id) >= (#{cursorDate}, #{cursorId})
AND e.genre = #{genre}
ORDER BY es.event_date ASC, e.id ASC
LIMIT #{limit}

mapper.update:
UPDATE tb_event
SET status = #{status}, updated_at = NOW()
WHERE id = #{eventId}
